#!/usr/bin/env bash
# Grader for one httrack-2026 ticket (docs/SPEC.md section 5; generated by
# scripts/real_sequence/render_run_sh.py from templates/run_automake.sh).
#
# cwd is the grading copy test.sh prepared: the agent's source, with tests/,
# every .gitignore and the other protected paths taken from the segment's
# trusted start tree, and this ticket's hidden test files overlaid. Nothing
# else in the copy is trusted: generated build files are deleted and rebuilt
# from the source, out of tree, with the system autotools.
#
# Exit 0 iff the build succeeds and every fail-to-pass (F2P) and pass-to-pass
# (P2P) test reports PASS in its automake .trs file (SKIP, XFAIL, XPASS, FAIL,
# ERROR and a missing .trs all count against). Per-group counts go to
# $ODYSSEY_OUT/details.json (the shape odyssey validate reads).
set -uo pipefail

TICKET="HTT-08"
F2P=(
    142_webhttrack-content-type.test
)
P2P=(
    00_runnable.test
    01_engine-mime.test
    01_engine-parse.test
    01_engine-savename.test
    15_local-types.test
    18_local-update.test
    61_webhttrack-locale.test
    63_webhttrack-home.test
    68_webhttrack-outdir-charset.test
    77_webhttrack-redirect.test
    78_webhttrack-sid.test
    81_webhttrack-maxsize.test
    82_webhttrack-browse-links.test
    83_webhttrack-argescape.test
    84_webhttrack-mirror-verbatim.test
    85_webhttrack-projpath.test
    89_webhttrack-error-overflow.test
    90_webhttrack-checkbox-clear.test
    91_webhttrack-directory.test
    141_webhttrack-warc-options.test
)

JOBS="${ODYSSEY_JOBS:-4}"
# Per-test wall-clock budget, enforced by the repo's own tests/test-timeout.sh
# (trusted copy). The slowest healthy test takes well under a minute.
export HTTRACK_TEST_TIMEOUT="${ODYSSEY_TEST_TIMEOUT:-150}"

src="$(pwd)"
work="$(mktemp -d)"
trap 'rm -rf "$work"' EXIT
build="$work/build"
started=$(date +%s)

# Every git call below uses a repository of our own, outside the tree (never a
# .git found in the copy), and reads no config the agent could have written.
export GIT_CONFIG_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null
git_() {
    git --git-dir="$work/clean.git" --work-tree="$src" -c safe.directory='*' \
        -c core.hooksPath=/dev/null -c core.fsmonitor=false "$@"
}

build_status=0
build_step=""
step() {
    # step <name> <command...>: run a build step, keep its log, stop at the first failure.
    build_step="$1"
    shift
    echo "== $TICKET build: $build_step"
    if ! "$@" >"$work/$build_step.log" 2>&1; then
        build_status=1
        tail -n 40 "$work/$build_step.log"
        return 1
    fi
}

# 1. Drop every generated file (configure, Makefile.in, objects, an in-tree
#    build of the agent's) by the trusted .gitignore files, so the build below
#    starts from source alone.
clean_generated() {
    git_ init -q && (cd "$src" && git_ clean -ffdXq)
}

step clean clean_generated &&
    step bootstrap autoreconf -fi "$src" &&
    mkdir -p "$build" &&
    step configure bash -c 'cd "$1" && "$2/configure" --quiet' _ "$build" "$src" &&
    step make make -C "$build" -j"$JOBS"
build_secs=$(( $(date +%s) - started ))

run_group() {
    # run_group <name> <tests...>: automake check of exactly these tests.
    local name="$1"
    shift
    [ "$build_status" -eq 0 ] || return 0
    echo "== $TICKET $name: $*"
    make -C "$build/tests" -j"$JOBS" check TESTS="$*" >"$work/$name.log" 2>&1
    echo "$?" >"$work/$name.status"
    grep -E '^(PASS|FAIL|SKIP|XFAIL|XPASS|ERROR):' "$work/$name.log" || true
}

run_group f2p "${F2P[@]}"
run_group p2p "${P2P[@]}"
total_secs=$(( $(date +%s) - started ))

# The verdict comes from the .trs files the system automake test driver wrote,
# never from make's exit status alone.
verdict=0
python3 -I - "$build/tests" "$work" "$TICKET" "$build_status" "$build_step" "$build_secs" "$total_secs" \
    "${ODYSSEY_OUT:-}" "${#F2P[@]}" "${F2P[@]}" "${P2P[@]}" <<'PY' || verdict=$?
import json
import sys
from pathlib import Path

tests_dir, work, ticket = Path(sys.argv[1]), Path(sys.argv[2]), sys.argv[3]
build_status, build_step = int(sys.argv[4]), sys.argv[5]
build_secs, total_secs, out = int(sys.argv[6]), int(sys.argv[7]), sys.argv[8]
n_f2p = int(sys.argv[9])
f2p, p2p = sys.argv[10:10 + n_f2p], sys.argv[10 + n_f2p:]


def result(test):
    trs = tests_dir / (test[:-len(".test")] + ".trs" if test.endswith(".test") else test + ".trs")
    try:
        for line in trs.read_text(errors="replace").splitlines():
            if line.startswith(":test-result:"):
                return line.split()[1]
    except OSError:
        pass
    return "MISSING"


def group(name, tests):
    status_file = work / f"{name}.status"
    results = {t: result(t) for t in tests} if build_status == 0 else {t: "NOT_BUILT" for t in tests}
    passed = sum(r == "PASS" for r in results.values())
    skipped = sum(r == "SKIP" for r in results.values())
    failed = sum(r in ("FAIL", "XFAIL", "XPASS") for r in results.values())
    errors = len(tests) - passed - skipped - failed
    return {"exit_code": int(status_file.read_text()) if status_file.exists() else None,
            "report": build_status == 0, "tests": len(tests), "passed": passed, "failed": failed,
            "errors": errors, "skipped": skipped, "results": results}


groups = {"fail_to_pass": group("f2p", f2p), "pass_to_pass": group("p2p", p2p)}
resolved = build_status == 0 and all(g["passed"] == g["tests"] > 0 for g in groups.values())
details = {"ticket": ticket, "resolved": resolved,
           "build": {"ok": build_status == 0, "failed_step": build_step if build_status else None,
                     "seconds": build_secs},
           "seconds": total_secs, **groups}
if out:
    Path(out).mkdir(parents=True, exist_ok=True)
    (Path(out) / "details.json").write_text(json.dumps(details, indent=2) + "\n")
print(json.dumps({"ticket": ticket, "resolved": resolved, "build_ok": build_status == 0,
                  "build_seconds": build_secs, "seconds": total_secs,
                  "f2p": groups["fail_to_pass"]["results"],
                  "p2p_not_passed": {t: r for t, r in groups["pass_to_pass"]["results"].items() if r != "PASS"}}))
sys.exit(0 if resolved else 1)
PY

if [ "$verdict" -eq 0 ]; then
    echo "== $TICKET resolved"
    exit 0
fi
echo "== $TICKET not resolved"
exit 1
